import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"21、【噬嗑】 震下離上","description":"橫渠易說 - 21、【噬嗑】 震下離上","frontmatter":{"title":"21、【噬嗑】 震下離上","description":"橫渠易說 - 21、【噬嗑】 震下離上"},"headers":[],"relativePath":"classics/hengqu/023.md","filePath":"classics/hengqu/023.md"}'),l={name:"classics/hengqu/023.md"};function t(n,a,s,d,c,o){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_21、【噬嗑】-震下離上" tabindex="-1">21、【噬嗑】 震下離上 <a class="header-anchor" href="#_21、【噬嗑】-震下離上" aria-label="Permalink to “21、【噬嗑】 震下離上”">​</a></h1><h3 id="彖曰-頤中有物曰噬嗑。噬嗑而亨-剛柔分-動而明-雷電合而章-柔得中而上行-雖不當位-利用獄也。" tabindex="-1">彖曰：頤中有物曰噬嗑。噬嗑而亨，剛柔分，動而明，雷電合而章，柔得中而上行，雖不當位，利用獄也。 <a class="header-anchor" href="#彖曰-頤中有物曰噬嗑。噬嗑而亨-剛柔分-動而明-雷電合而章-柔得中而上行-雖不當位-利用獄也。" aria-label="Permalink to “彖曰：頤中有物曰噬嗑。噬嗑而亨，剛柔分，動而明，雷電合而章，柔得中而上行，雖不當位，利用獄也。”">​</a></h3><p>子路禮樂文章未足盡為政之道，以其重然諾，言為眾信，故片言可以折獄。如易“利用獄”，“利用刑人”，皆非卦爻盛德，適能是而已焉</p><p>九五分而下，初六分而上，故曰“剛柔分”。“合而章”，合而成文也。</p><h3 id="象曰-雷電-噬嗑-先王以明罰法。" tabindex="-1">象曰：雷電，噬嗑，先王以明罰法。 <a class="header-anchor" href="#象曰-雷電-噬嗑-先王以明罰法。" aria-label="Permalink to “象曰：雷電，噬嗑，先王以明罰法。”">​</a></h3><p>六自初而進之於五，故曰“上行”。</p><h3 id="初九-屨校滅趾-無咎。-象曰-屨校滅趾-不行也。" tabindex="-1">初九，屨校滅趾，無咎。 象曰：“屨校滅趾”，不行也。 <a class="header-anchor" href="#初九-屨校滅趾-無咎。-象曰-屨校滅趾-不行也。" aria-label="Permalink to “初九，屨校滅趾，無咎。 象曰：“屨校滅趾”，不行也。”">​</a></h3><p>戒之在初，小懲可止，故無咎。</p><h3 id="六二-噬膚滅鼻-無咎。-象曰-噬膚滅鼻-乘剛也。" tabindex="-1">六二，噬膚滅鼻，無咎。 象曰：“噬膚滅鼻”，乘剛也。 <a class="header-anchor" href="#六二-噬膚滅鼻-無咎。-象曰-噬膚滅鼻-乘剛也。" aria-label="Permalink to “六二，噬膚滅鼻，無咎。 象曰：“噬膚滅鼻”，乘剛也。”">​</a></h3><p>六三居有過之地而己噬之，乘剛而動，為力不勞，動未過中，故無咎。</p><h3 id="六三-噬臘肉遇毒-小吝無咎。-象曰-遇毒-位不當也。" tabindex="-1">六三，噬臘肉遇毒，小吝無咎。 象曰：“遇毒”，位不當也。 <a class="header-anchor" href="#六三-噬臘肉遇毒-小吝無咎。-象曰-遇毒-位不當也。" aria-label="Permalink to “六三，噬臘肉遇毒，小吝無咎。 象曰：“遇毒”，位不當也。”">​</a></h3><p>所間在四，四為剛陽，故曰“臘肉”；非禮傷義，故曰“遇毒”。能以為毒而舍之，雖近不相得，小有吝而無咎也。</p><h3 id="九四-噬乾胏-得金矢-利艱貞-吉。-象曰-利艱貞吉-未光也。" tabindex="-1">九四，噬乾胏，得金矢，利艱貞，吉。 象曰：“利艱貞吉”，未光也。 <a class="header-anchor" href="#九四-噬乾胏-得金矢-利艱貞-吉。-象曰-利艱貞吉-未光也。" aria-label="Permalink to “九四，噬乾胏，得金矢，利艱貞，吉。 象曰：“利艱貞吉”，未光也。”">​</a></h3><p>五為陰柔，故喻乾胏；能守正得剛直之義，故艱貞吉，其德光大則其正非艱也。</p><h3 id="六五-噬乾肉-得黃金-貞厲無咎。-象曰-貞厲無咎-得當也。" tabindex="-1">六五，噬乾肉，得黃金，貞厲無咎。 象曰：“貞厲無咎”，得當也。 <a class="header-anchor" href="#六五-噬乾肉-得黃金-貞厲無咎。-象曰-貞厲無咎-得當也。" aria-label="Permalink to “六五，噬乾肉，得黃金，貞厲無咎。 象曰：“貞厲無咎”，得當也。”">​</a></h3><h3 id="上九-何校滅耳-兇。-象曰-何校滅耳-聰不明也。" tabindex="-1">上九，何校滅耳，兇。 象曰：“何校滅耳”，聰不明也。 <a class="header-anchor" href="#上九-何校滅耳-兇。-象曰-何校滅耳-聰不明也。" aria-label="Permalink to “上九，何校滅耳，兇。 象曰：“何校滅耳”，聰不明也。”">​</a></h3><p>九四、</p><h3 id="上九-難於屈服-故曰-乾肉-。得居中持堅之義-正而危則得無咎也。" tabindex="-1">上九，難於屈服，故曰“乾肉”。得居中持堅之義，正而危則得無咎也。 <a class="header-anchor" href="#上九-難於屈服-故曰-乾肉-。得居中持堅之義-正而危則得無咎也。" aria-label="Permalink to “上九，難於屈服，故曰“乾肉”。得居中持堅之義，正而危則得無咎也。”">​</a></h3>',18)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
